//
//  Advanced Chromatic Aberration
//  Native Metal Shader - Lens Distortion
//

#include <metal_stdlib>
using namespace metal;

struct Uniforms {
    float4x4 MVP;
    float4 OutputSize;
    float4 SourceSize;
    float4 OriginalSize;
    uint FrameCount;
    float aberration_strength;
    float radial_distortion;
    float color_fringing;
    float vignette_strength;
};

struct VertexIn {
    float4 position [[attribute(0)]];
    float2 texCoord [[attribute(1)]];
};

struct VertexOut {
    float4 position [[position]];
    float2 texCoord;
};

vertex VertexOut main0(
    VertexIn in [[stage_in]],
    constant Uniforms &uniforms [[buffer(0)]]
)
{
    VertexOut out;
    out.position = uniforms.MVP * in.position;
    out.texCoord = in.texCoord;
    return out;
}

// Barrel distortion
float2 barrelDistortion(float2 uv, float strength) {
    float2 center = uv - 0.5;
    float r2 = dot(center, center);
    float distortion = 1.0 + strength * r2;
    return center * distortion + 0.5;
}

fragment float4 fragment_main(
    VertexOut in [[stage_in]],
    texture2d<float> sourceTexture [[texture(0)]],
    constant Uniforms &uniforms [[buffer(0)]]
)
{
    constexpr sampler textureSampler(
        mag_filter::linear,
        min_filter::linear,
        address::clamp_to_edge
    );

    float2 uv = in.texCoord;
    float2 center = uv - 0.5;
    float dist = length(center);

    // Radial chromatic aberration
    float aberration = uniforms.aberration_strength * dist;

    // Different distortion for each channel
    float2 uvR = barrelDistortion(uv, uniforms.radial_distortion * (1.0 + aberration * 0.02));
    float2 uvG = barrelDistortion(uv, uniforms.radial_distortion);
    float2 uvB = barrelDistortion(uv, uniforms.radial_distortion * (1.0 - aberration * 0.02));

    // Sample each channel separately
    float r = sourceTexture.sample(textureSampler, uvR).r;
    float g = sourceTexture.sample(textureSampler, uvG).g;
    float b = sourceTexture.sample(textureSampler, uvB).b;

    float3 color = float3(r, g, b);

    // Color fringing (purple/green edges)
    float2 offset = normalize(center) * uniforms.color_fringing * 0.01;
    float3 fringe1 = sourceTexture.sample(textureSampler, uv + offset).rgb;
    float3 fringe2 = sourceTexture.sample(textureSampler, uv - offset).rgb;

    // Purple fringing on one side, green on the other
    float3 purpleFringe = float3(0.8, 0.2, 0.8);
    float3 greenFringe = float3(0.2, 0.8, 0.2);

    float edgeMask = smoothstep(0.3, 0.7, dist);
    color = mix(color, 
                mix(fringe1 * purpleFringe, fringe2 * greenFringe, 0.5),
                edgeMask * uniforms.color_fringing * 0.3);

    // Vignette
    float vignette = 1.0 - dist * dist * uniforms.vignette_strength;
    color *= vignette;

    // Edge darkening (lens falloff)
    float edgeDarken = 1.0 - smoothstep(0.5, 1.0, dist) * 0.5;
    color *= edgeDarken;

    return float4(color, 1.0);
}

